import{z as d,x as A,o as r,c as B,q as i,j as o,D as e,d as E,s as l,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"纠错码直觉","description":"","frontmatter":{"title":"纠错码直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/error-correcting-intuition.md","filePath":"cs/error-correcting-intuition.md","lastUpdated":1791063341000}'),m={name:"cs/error-correcting-intuition.md"};function p(D,a,u,c,C,h){const t=A("Mermaid");return r(),B("div",null,[a[2]||(a[2]=i('<h1 id="纠错码直觉" tabindex="-1">纠错码直觉 <a class="header-anchor" href="#纠错码直觉" aria-label="Permalink to &quot;纠错码直觉&quot;">​</a></h1><div class="epigraph"><p>检错靠码字互相离开；纠错则是把收到的串判给最近的那个合法点。</p><footer>—— 据 Hamming, Error Detecting and Error Correcting Codes, 1950；Shannon, 1948 整理</footer></div><p>上一课<a href="/cs/mutual-information">联合熵与互信息</a>钉死了：平均不确定度有下界，压缩不能无代价地短于熵。本课不重讲 \\(H(X)\\)，也不从信道容量定理另起一篇综述。缺口是：熵假定符号已经正确到达。第一课承认翻转会发生，到现在还没有尺子说「错了多少、怎样改回来」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>合法码字若占满 \\(\\Sigma^n\\)，一位翻转仍是某个合法字，接收方无法发现。缺口因此不是更大的字母表，而是<strong>不用完</strong>所有串：选出子集 \\(C\\subset\\Sigma^n\\)，使任意两个码字的汉明距离至少为 \\(d\\)。则少于 \\(d\\) 位的错可被发现；少于 \\(d/2\\) 的错，按最近邻可被纠正。</p><p>Hamming 的 \\((7,4)\\) 码用 3 位奇偶把 \\(d\\) 放到 \\(3\\)，纠正 1 位。本课只钉距离与球，不把线性码的生成矩阵写完，也不证明 Shannon 第二定理。</p><h3 id="奇偶校验不是纠错" tabindex="-1">奇偶校验不是纠错 <a class="header-anchor" href="#奇偶校验不是纠错" aria-label="Permalink to &quot;奇偶校验不是纠错&quot;">​</a></h3><p>一比特奇偶使 \\(d=2\\)，发现奇数位错，不能定位。纠错需要定位：冗余必须随长度增长。把 CRC 的「几乎总能发现」说成「已经纠正」，后课存储阵列会把检错和重传混成一步。</p><p><span class="marginnote">汉明距离是翻转位数，与熵无关：几何先于概率。Shannon 说噪声信道上仍可任意可靠，条件是速率低于容量且块够长；Hamming 给出短块、可构造的几何。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义 \\(d(u,v)\\) 为相异位数。码 \\(C\\) 的最小距离 \\(d_{\\min}=\\min_{c\\neq c&#39;}d(c,c&#39;)\\)。译码：在 \\(\\{u:d(r,u)\\le t\\}\\) 里找唯一码字，其中 \\(2t+1\\le d_{\\min}\\)。重复码、奇偶、Hamming 码是三条由短到长的例子；本课用它们说明冗余换距离，不选哪一种做后课内存的唯一方案。</p>',11)),(r(),o(s,null,{default:e(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENT%5B%22%E7%86%B5%EF%BC%9A%E6%9C%80%E7%9F%AD%E6%97%A0%E5%86%97%E4%BD%99%22%5D%20--%3E%20RED%5B%22%E7%95%99%E4%B8%8B%E7%A9%BA%E9%9A%99%22%5D%0A%20%20RED%20--%3E%20DIST%5B%22%E6%9C%80%E5%B0%8F%E8%B7%9D%E7%A6%BB%20d%22%5D%0A%20%20DIST%20--%3E%20DEC%5B%22%E6%9C%80%E8%BF%91%E9%82%BB%E8%AF%91%E7%A0%81%22%5D%0A%20%20DEC%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%B8%83%E5%B0%94%E4%B8%8E%E7%94%B5%E8%B7%AF%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,[n("span",{class:"marginnote"},"代入数字：\\((7,4)\\) 码发 7 位，其中 4 位是数据、3 位是校验。\\(d_{\\min}=3\\)，由 \\(2t+1\\le d_{\\min}\\) 得 \\(t=1\\)：任何 1 位翻转都落在原码字周围半径 1 的球里，而别的码字至少隔 3 位，于是能唯一判回；若错 2 位，两个球可能重叠，就只能发现、不能定位。")],-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[E("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,"存储与总线把这一层做成 ECC DIMM、磁盘的 CRC：发现了可以重读或报警，纠正了可以静默恢复。后课 SRAM 阵列会假定位翻转是稀有事件；本课只提供「为何加校验位」的几何。编码是线性时，校验是矩阵乘，电路上是一组异或——布尔代数还没有正式进场，本课不把门图画出来。",-1)),a[6]||(a[6]=n("p",null,"距离保证最坏情况；平均情况可以更好。概率模型与几何模型要分开写：上一课的熵管速率，本课的 \\(d\\) 管可纠正半径。",-1)),(r(),o(s,null,{default:e(()=>[l(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%94%B6%E5%88%B0%E4%B8%B2%20r%22%5D%20--%3E%20D%5B%22%E7%AE%97%20r%20%E5%88%B0%E6%AF%8F%E4%B8%AA%E7%A0%81%E5%AD%97%E7%9A%84%E6%B1%89%E6%98%8E%E8%B7%9D%E7%A6%BB%22%5D%0A%20%20D%20--%3E%20Q%7B%22%E6%9C%80%E8%BF%91%E7%9A%84%E7%A0%81%E5%AD%97%E5%94%AF%E4%B8%80%E4%B8%94%E8%B7%9D%E7%A6%BB%E4%B8%8D%E8%B6%85%E8%BF%87%20t%EF%BC%9F%22%7D%0A%20%20Q%20--%20%22%E6%98%AF%22%20--%3E%20FIX%5B%22%E5%88%A4%E7%BB%99%E8%AF%A5%E7%A0%81%E5%AD%97%EF%BC%8C%E9%9D%99%E9%BB%98%E7%BA%A0%E6%AD%A3%22%5D%0A%20%20Q%20--%20%22%E5%90%A6%22%20--%3E%20BAD%5B%22%E8%B6%85%E5%87%BA%E7%BA%A0%E6%AD%A3%E5%8D%8A%E5%BE%84%EF%BC%9A%E5%8F%AA%E8%83%BD%E6%8A%A5%E8%AD%A6%E6%88%96%E9%87%8D%E4%BC%A0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">可以把它想象成海上的岛屿：每个合法码字是一座岛，半径 \\(t\\) 的浅滩归这座岛管。船（收到的串）只要搁浅在哪片浅滩上，就知道该回哪个港口；漂出所有浅滩，才需要求救（重传）。\\(d_{\\min}\\) 越大，浅滩越宽，能扛的风浪（错误位数）就越大。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Reed–Solomon、LDPC、不把容量 \\(C\\) 的随机编码证明展开。也不把加密完整性（MAC）当成纠错：主动攻击不是独立比特翻转。字符 UTF-8 的非法序列检测不是汉明码。</p><p>后课默认：谈到检错、纠错，先问最小距离；奇偶只能检、不能纠。电路如何实现校验，从布尔代数开始。</p><p><span class="marginnote">初学者容易以为 CRC 或哈希校验能「纠正」错误，实际上它们只回答「变没变」，不回答「哪一位错了」——没有距离结构，就没有纠正半径。纠错必须在发送前把冗余编进去，收到之后才补救是来不及的。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不用完 \\(\\Sigma^n\\)，码字之间才有距离。</li><li>\\(d_{\\min}\\) 决定能检几位、纠几位；奇偶只是 \\(d=2\\)。</li><li>几何（Hamming）与熵（Shannon）分工：一个管距离，一个管速率。</li><li>出处：Hamming, 1950；Shannon, 1948。</li></ul>',7))])}const f=d(m,[["render",p]]);export{g as __pageData,f as default};
